// Combine les régimes de neutre HTA (isolé/compensé/résistant) et les schémas de liaison à la
// terre BT (TT/TN/IT) : l'un ou l'autre s'applique selon que le site est HTA, BT, ou les deux.
const LISTE_REGIME_NEUTRE = ["Neutre isolé (HTA)", "Neutre compensé / résonnant (HTA)", "Neutre résistant (HTA)", "TT (BT)", "TN-S (BT)", "TN-C (BT)", "TN-C-S (BT)", "IT (BT)"];
// Description courte de chaque régime, affichée en aide contextuelle près du champ dans la fiche
// du local — pour rappeler concrètement ce que chaque sigle signifie sans avoir à le rechercher.
const REGIME_NEUTRE_DESCRIPTIONS = {
  "Neutre isolé (HTA)": "Neutre non relié à la terre (ou via une forte impédance) — un premier défaut à la terre ne provoque pas de coupure, mais doit être détecté et éliminé rapidement.",
  "Neutre compensé / résonnant (HTA)": "Neutre mis à la terre via une bobine de compensation (bobine de Petersen) accordée sur la capacité du réseau — limite fortement le courant de défaut à la terre.",
  "Neutre résistant (HTA)": "Neutre mis à la terre via une résistance, qui limite le courant de défaut à une valeur définie tout en permettant sa détection.",
  "TT (BT)": "Neutre relié à la terre côté source ; masses des installations reliées à une prise de terre locale, indépendante — protection par disjoncteur différentiel obligatoire.",
  "TN-S (BT)": "Neutre relié à la terre côté source ; masses reliées au neutre via un conducteur de protection (PE) distinct du neutre (N) sur tout le circuit.",
  "TN-C (BT)": "Neutre relié à la terre côté source ; fonctions neutre et protection assurées par un seul conducteur commun (PEN) sur tout le circuit.",
  "TN-C-S (BT)": "Combine TN-C en amont (conducteur PEN commun) et TN-S en aval (neutre N et protection PE séparés) — la séparation PEN→N+PE ne doit jamais être inversée.",
  "IT (BT)": "Neutre isolé de la terre (ou via forte impédance) ; masses reliées à la terre — un premier défaut n'entraîne pas de coupure, surveillé par un contrôleur permanent d'isolement (CPI).",
};
// Schéma de liaison à la terre BT reconnu dans le régime de neutre d'un local (liste ou saisie libre).
function regimeBTDuLocal(regimeNeutre) {
  const r = String(regimeNeutre || "");
  if (/TN-?C-?S/i.test(r)) return "TN-C-S";
  if (/TN-?C(?![-A-Za-z])/i.test(r)) return "TN-C";
  if (/TN-?S/i.test(r)) return "TN-S";
  if (/\bTT\b/.test(r)) return "TT";
  if (/\bIT\b/.test(r)) return "IT";
  return null;
}
// Points de contrôle du tableau BT selon le schéma de liaison à la terre ; la norme choisie sur le
// local (comme la « Norme du poste » côté HTA) ne change que la référence rappelée à la suite.
const POINTS_CONTROLE_REGIME_BT = {
  "TT": "Schéma TT : protection contre les contacts indirects par dispositifs différentiels (DDR) — vérifier la résistance de la prise de terre des masses (RA × IΔn ≤ 50 V) et le déclenchement des DDR (bouton test, seuil et temps).",
  "TN-S": "Schéma TN-S : coupure automatique par les protections contre les surintensités (ou DDR) — vérifier la continuité du conducteur PE et des liaisons équipotentielles, et l'impédance de boucle (Zs × Ia ≤ U0).",
  "TN-C": "Schéma TN-C : conducteur PEN commun (section minimale usuelle 10 mm² cuivre / 16 mm² aluminium), sans DDR possible sur le PEN — vérifier la continuité du PEN et l'impédance de boucle.",
  "TN-C-S": "Schéma TN-C-S : séparation PEN → N + PE réalisée une seule fois et jamais inversée, DDR possible seulement en aval de la séparation — vérifier la continuité du PE/PEN et l'impédance de boucle.",
  "IT": "Schéma IT : contrôleur permanent d'isolement (CPI) obligatoire avec signalisation du premier défaut — vérifier le fonctionnement du CPI et organiser la recherche et l'élimination rapide du premier défaut (le second défaut provoque la coupure).",
};
const REFERENCE_NORME_REGIME_BT = {
  "NF C 15-100": " (NF C 15-100, article 411 : protection contre les contacts indirects).",
  "NF EN 61439": " Tableau selon NF EN 61439 : le schéma de liaison à la terre fait partie des données d'entrée du constructeur du tableau — vérifier que son circuit de protection (barres PE/PEN, continuité) est conforme à ce schéma.",
  "NF EN 60439 (ancienne)": " Tableau selon NF EN 60439 (remplacée par la NF EN 61439) : vérifier que son circuit de protection (barres PE/PEN, continuité) correspond bien au schéma de liaison à la terre de l'installation.",
  "NF C 14-100": " NF C 14-100 (branchement) : en distribution publique, le schéma de liaison à la terre est imposé par le distributeur (en général TT) — s'y référer.",
  "DIN": " Norme DIN (VDE 0100-410) : même principe de protection contre les contacts indirects selon le schéma.",
};
function pointsControleRegimeBT(regimeNeutre, normeTableau) {
  const regime = regimeBTDuLocal(regimeNeutre);
  if (!regime) return null;
  const normes = Array.isArray(normeTableau) ? (normeTableau.length ? normeTableau : ["NF C 15-100"]) : [normeTableau || "NF C 15-100"];
  return POINTS_CONTROLE_REGIME_BT[regime] + normes.map((n) => REFERENCE_NORME_REGIME_BT[n] || "").join("");
}
// --- Régime de neutre séparé HTA / BT (un local peut avoir les deux) ---------------------------
const LISTE_REGIME_NEUTRE_HTA = ["Neutre isolé (HTA)", "Neutre compensé / résonnant (HTA)", "Neutre résistant (HTA)"];
const LISTE_REGIME_NEUTRE_BT_LOCAL = ["TT (BT)", "TN-S (BT)", "TN-C (BT)", "TN-C-S (BT)", "IT (BT)"];
// Anciennes fiches : un seul champ « regimeNeutre » (HTA ou BT) — réparti à la volée.
function regimesNeutreDuLocal(l) {
  const ancien = String(l?.regimeNeutre || "");
  const hta = l?.regimeNeutreHTA !== undefined ? l.regimeNeutreHTA : (/HTA/i.test(ancien) && !/\//.test(ancien) ? ancien : "");
  const bt = l?.regimeNeutreBT !== undefined ? l.regimeNeutreBT : (regimeBTDuLocal(ancien) ? (LISTE_REGIME_NEUTRE_BT_LOCAL.find((x) => x.startsWith(regimeBTDuLocal(ancien) + " ")) || ancien) : "");
  return { hta, bt };
}
const texteRegimesNeutre = (l) => { const { hta, bt } = regimesNeutreDuLocal(l); return [hta && `HTA : ${hta.replace(/ \(HTA\)$/, "")}`, bt && `BT : ${bt.replace(/ \(BT\)$/, "")}`].filter(Boolean).join(" · "); };
// --- Normes du tableau BT (plusieurs possibles, ex. NF C 15-100 + NF EN 61439) -------------------
function normesTableauDuLocal(l) {
  if (Array.isArray(l?.normesTableauBT) && l.normesTableauBT.length) return l.normesTableauBT;
  return l?.normeTableauBT ? [l.normeTableauBT] : [];
}
const NORMES_ENSEMBLE = ["NF EN 61439", "NF EN 60439 (ancienne)"];
const localEnsembleNormalise = (l) => normesTableauDuLocal(l).some((n) => NORMES_ENSEMBLE.includes(n));
const LISTE_FORME_SEPARATION = ["Forme 1", "Forme 2a", "Forme 2b", "Forme 3a", "Forme 3b", "Forme 4a", "Forme 4b"];
