// Tolérance CEI 60076-1 : ±0,5 % du rapport déclaré (prise principale).
function calcToleranceRapportTransfo(rapportTheorique) {
  if (rapportTheorique === null) return null;
  return { min: Math.round(rapportTheorique * 0.995 * 1000) / 1000, max: Math.round(rapportTheorique * 1.005 * 1000) / 1000 };
}

// Fabrique de schéma Onduleur : chaque section de mesures réseau peut être triphasée (par défaut)
// ou monophasée (un seul point de mesure, réutilise la clé "l1"/"p1"/"s1"/"cosphi1" pour rester
// compatible avec les calculs déjà en place — taux de charge, tableaux consolidés, etc.).
function champsMono(unit, label) {
  return [F("l1", label || "Valeur", unit)];
}
// Seuils indicatifs de distorsion harmonique — repères de planification génériques (EN 50160 pour
// le THdV en BT ; CEI 61000-3-6 pour les niveaux HTA/HTB/THT ; IEEE 519-2014 pour le ThdI, qui
// dépend en toute rigueur du rapport Isc/IL — 10% est un repère de vigilance moyen en l'absence de
// calcul précis). Valeur générique donnée à titre indicatif, à confirmer selon le gestionnaire de
// réseau et le niveau de tension concerné. Volontairement PAS appliqué au réseau normal/secours
// (entrée) d'un onduleur ou d'un redresseur : cette mesure est prise en AMONT de leur propre
// redresseur, et sa distorsion (notamment en courant) dépend directement du type de redresseur
// (6/12 impulsions, IGBT…) plutôt que d'un seuil réseau générique.
function champsSeuilThdv(champs) {
  return [...champs,
    { key: "tol_min", label: "Seuil bas", unit: null, hidden: true, compute: () => "" },
    { key: "tol_max", label: "Seuil indicatif THdV (EN 50160 / CEI 61000-3-6)", unit: "%", compute: () => 8 },
  ];
}
function champsSeuilThdi(champs) {
  return [...champs,
    { key: "tol_min", label: "Seuil bas", unit: null, hidden: true, compute: () => "" },
    { key: "tol_max", label: "Seuil indicatif ThdI (repère général — dépend en réalité du rapport Isc/IL, IEEE 519-2014)", unit: "%", compute: () => 10 },
  ];
}
// Déséquilibre de tension : seuil normatif EN 50160 (réseau BT, 95 % du temps sur 10 min). Le champ
// "desequilibre" doit déjà être présent dans champs (ex. via champsTriphase(..., true)). phaseKeys:
// [] désactive la coloration par défaut de L1/L2/L3 : seul le champ "desequilibre" est comparé au
// seuil, pas les valeurs de tension brutes.
function champsSeuilDesequilibre(champs) {
  return [...champs,
    { key: "tol_min", label: "Seuil bas", unit: null, hidden: true, unitFrom: "desequilibre", phaseKeys: [], compute: () => "" },
    { key: "tol_max", label: "Seuil indicatif de déséquilibre (EN 50160)", unit: "%", unitFrom: "desequilibre", phaseKeys: [], compute: () => 2 },
  ];
}
// FP seul, sans "Nature" — pour le réseau normal, où seule la valeur du facteur de puissance
// mesuré à l'écran a un sens (l'onduleur ne donne pas d'indication de nature inductif/capacitif).
function fpSeulItem(mono) {
  if (mono) return [F("fp1", "FP", null)];
  return [F("fp1", "FP L1", null), F("fp2", "FP L2", null), F("fp3", "FP L3", null)];
}
// Relevé complet de puissance en utilisation : P et S sont relevés directement à l'écran de
// l'onduleur (saisie manuelle), Q est calculé (Q = √(S²-P²)), et le cos φ fondamental + sa nature
// (inductif/capacitif/résistif) sont relevés séparément — c'est le déphasage sur le fondamental,
// une grandeur différente de P/S/Q qui elles tiennent compte des harmoniques.
function qCalculeField(idx, mono) {
  return {
    key: `q${idx}`, label: mono ? "Q calculé" : `Q calculé L${idx}`, unit: "kVAR",
    compute: (f) => {
      const p = numOf(f[`p${idx}`]), s = numOf(f[`s${idx}`]);
      if (p === null || s === null) return "";
      const q2 = s * s - p * p;
      return Math.round((q2 < 0 ? 0 : Math.sqrt(q2)) * 100) / 100;
    },
  };
}
function cosPhiFondamentalItem(mono) {
  if (mono) {
    return [
      F("p1", "P relevé", "kW"), F("s1", "S relevé", "kVA"), qCalculeField(1, true),
      F("fp1", "Cos φ fondamental", null),
      F("nature1", "Nature", null, ["Inductif", "Capacitif", "Résistif"]),
    ];
  }
  return [
    F("p1", "P relevé L1", "kW"), F("p2", "P relevé L2", "kW"), F("p3", "P relevé L3", "kW"),
    F("s1", "S relevé L1", "kVA"), F("s2", "S relevé L2", "kVA"), F("s3", "S relevé L3", "kVA"),
    qCalculeField(1, false), qCalculeField(2, false), qCalculeField(3, false),
    F("fp1", "Cos φ fondamental L1", null), F("fp2", "Cos φ fondamental L2", null), F("fp3", "Cos φ fondamental L3", null),
    F("nature1", "Nature L1", null, ["Inductif", "Capacitif", "Résistif"]),
    F("nature2", "Nature L2", null, ["Inductif", "Capacitif", "Résistif"]),
    F("nature3", "Nature L3", null, ["Inductif", "Capacitif", "Résistif"]),
  ];
}
function puissanceFpItem(mono) {
  if (mono) {
    return [
      F("fp1", "FP", null),
      F("nature1", "Nature", null, ["Inductif", "Capacitif", "Résistif"]),
    ];
  }
  return [
    F("fp1", "FP L1", null), F("fp2", "FP L2", null), F("fp3", "FP L3", null),
    F("nature1", "Nature L1", null, ["Inductif", "Capacitif", "Résistif"]),
    F("nature2", "Nature L2", null, ["Inductif", "Capacitif", "Résistif"]),
    F("nature3", "Nature L3", null, ["Inductif", "Capacitif", "Résistif"]),
  ];
}
function tensionCourantItem(mono, unit, label) {
  if (mono) return champsMono(unit, label);
  const decimals = unit === "V" ? 0 : 1;
  const champs = champsTriphase(unit, label, decimals, "moyenne", true);
  // Déséquilibre de tension : seuil EN 50160, ne s'applique qu'aux grandeurs en Volts (pas de seuil
  // EN 50160 équivalent pour le déséquilibre de courant).
  return unit === "V" ? champsSeuilDesequilibre(champs) : champs;
}
