// Actions possibles suite au déclenchement d'un relais de protection transformateur — les 4
// dernières options couvrent les cas où le relais informe sans forcément couper (report à
// distance, ventilation forcée), en plus des actions de coupure déjà existantes.
const ACTIONS_RELAIS_TRANSFORMATEUR = [
  "Sans action du relais", "Mise hors tension", "Mise hors charge", "Mise hors tension et hors charge",
  "Voyant lumineux", "Alarme", "Report GTC", "Mise en route ventilation", "SANS OBJET",
];
// Convertit une valeur de résistance d'isolement vers les MΩ, quelle que soit l'unité choisie
// (Ω/MΩ/GΩ) — indispensable avant de comparer à un seuil, sous peine de comparer des grandeurs
// incompatibles entre elles.
// Tailles de vis/écrou courantes sur les connexions de puissance transformateur.
const LISTE_TAILLE_VIS = ["M6", "M8", "M10", "M12", "M14", "M16", "M20"];
// Couple de serrage : les valeurs varient significativement selon le type de connecteur (cuivre,
// aluminium, cosse à sertir ou méplat), la marque et le modèle — pas de table générique fiable à
// proposer pour les connexions de puissance (plateau, bornes BT/HT). Seule exception vérifiée :
// les borniers de terre à vis, où 5/10/15 N·m pour M6/M8/M10 est une valeur couramment documentée
// (repère uniquement, à vérifier ; ne s'applique pas aux connexions de puissance).
const COUPLE_TERRE_REFERENCE = { "M6": 5, "M8": 10, "M10": 15 };
// Couples de serrage pour transformateur sec enrobé — plages MT et barres BT, convertis en N·m.
// Valeurs confirmées identiques d'un constructeur à l'autre pour ce type de connexion (retour
// terrain), donc présentées comme repère général plutôt que rattachées à une gamme précise.
const COUPLE_TRIHAL_MT = { "M8": 9.8, "M10": 19.6, "M12": 29.4, "M14": 49.1 };
const COUPLE_TRIHAL_BT = { "M8": 12.3, "M10": 24.5, "M12": 44.1, "M14": 68.7, "M16": 98.1 };
// Couples d'étanchéité pour transformateur huile (goujons de traversées/passe-barres, vis de
// liaison couvercle-cuve, bouchons) — d'après documentation transformateur fournie par
// l'utilisateur (photo, fabricant non identifié sur l'extrait — à vérifier que c'est bien le
// modèle concerné avant de s'y fier). Valeurs vérifiées par cohérence interne (m.N ≈ m.kg × 10).
const COUPLE_ETANCHEITE_HUILE = {
  goujons: { "M8": 15, "M10": 24 },
  passe_barres: { "M6": 3 },
  couvercle_cuve: { "M8": 18, "M10": 24 },
  bouchon_remplissage: { "M22": 120 },
  bouchon_vidange: { "1\"": 250 },
};
function aideCoupleEtancheite(taille, sousType) {
  const table = COUPLE_ETANCHEITE_HUILE[sousType];
  if (!taille || !table || !table[taille]) return "Aucune valeur disponible pour cette taille — se référer à la documentation du fabricant.";
  return `Repère (documentation transformateur fournie, fabricant non identifié sur l'extrait) pour ${taille} : ${table[taille]} N·m — vérifier qu'il s'agit bien du modèle concerné avant de s'y fier.${texteDouille(taille)}`;
}
// Correspondance vis/écrou métrique ISO -> taille de douille/clé plate (cotes "sur plats", norme
// DIN 931/934 pour les hexagonaux standards) — valeurs normalisées, valables pour une tête ou un
// écrou hexagonal standard ; une vis à tête différente (Allen/BTR, Torx…) ne s'y retrouve pas.
const DOUILLE_METRIQUE = { "M4": 7, "M5": 8, "M6": 10, "M8": 13, "M10": 17, "M12": 19, "M14": 22, "M16": 24, "M18": 27, "M20": 30, "M22": 32, "M24": 36 };
function texteDouille(taille) {
  return DOUILLE_METRIQUE[taille] ? ` Douille/clé : ${DOUILLE_METRIQUE[taille]} mm (hexagonal standard — ne s'applique pas à une tête Allen/BTR ou Torx).` : "";
}
function aideCoupleSerrage(taille, typeConnexion) {
  if (!taille) return "";
  if (typeConnexion === "terre" && COUPLE_TERRE_REFERENCE[taille]) {
    return `Repère indicatif pour un bornier de terre à vis ${taille} : ${COUPLE_TERRE_REFERENCE[taille]} N·m — à vérifier, ne s'applique pas à une connexion de puissance (cosse/méplat).${texteDouille(taille)}`;
  }
  if (typeConnexion === "mt" && COUPLE_TRIHAL_MT[taille]) {
    return `Repère pour les plages MT en ${taille} : ${COUPLE_TRIHAL_MT[taille]} N·m (effort maximum sur les plages MT : 500 N).${texteDouille(taille)}`;
  }
  if (typeConnexion === "bt" && COUPLE_TRIHAL_BT[taille]) {
    return `Repère pour les barres BT en ${taille} : ${COUPLE_TRIHAL_BT[taille]} N·m.${texteDouille(taille)}`;
  }
  return `Aucune valeur générique fiable pour une connexion de puissance ${taille} — le couple varie selon le connecteur (cuivre/aluminium, cosse ou méplat) et le constructeur. Se référer à la documentation du fabricant ou à l'étiquette de l'appareil.${texteDouille(taille)}`;
}
// Couples de serrage indicatifs par section de conducteur (bornes à vis) — repère fourni par
// l'utilisateur ; à vérifier sur la documentation du fabricant de la borne concernée avant de s'y
// fier, un fabricant/modèle de bornier pouvant préconiser des valeurs différentes.
const COUPLE_SERRAGE_CONDUCTEUR = {
  "1,5 mm²": "1,5 – 2,0", "2,5 mm²": "2,0 – 2,5", "4 mm²": "2,0 – 2,5", "6 mm²": "2,0 – 3,0",
  "10 mm²": "2,5 – 3,5", "16 mm²": "3,0 – 4,0", "25 mm²": "4 – 5", "35 mm²": "5 – 6",
};
// Couples de serrage préconisés par SERMES Electric Systems pour ses équipements de compensation
// (notice constructeur « Couples de serrage pour équipements de compensation », photo fournie par
// l'utilisateur) — en N·m. Contacteurs : [bornes de puissance, bornes de commande].
const COUPLES_SERMES_COMPENSATION = {
  "Contacteur BJ K3-18": [1.3, 1.0], "Contacteur BJ K3-32": [2.8, 1.0], "Contacteur BJ K3-62 / BJ K3-74": [4.0, 1.0], "Contacteur BJ K3-90": [6.5, 1.0],
  "Condensateur — bornes jusqu'à 16 mm²": 1.3, "Condensateur — bornes de 25 mm²": 2.5, "Condensateur — boulon de mise à la terre": 10.0,
  "Coupe-circuit fusibles — embase NH-00, étrier M5": 3.0, "Coupe-circuit fusibles — sectionneur NH-00, étrier M5": 3.0,
  "Coupe-circuit fusibles — embase NH-00, étrier M8": 12.0, "Coupe-circuit fusibles — sectionneur NH-00, étrier M8": 12.0,
  "Bornes de puissance — borne à vis 16 mm²": 1.6, "Bornes de puissance — borne à vis 35 mm²": 3.0,
  "Jeu de barres / barre PE / PEN — Tensilock M10": 49, "Jeu de barres / barre PE / PEN — Tensilock M12": 85,
};
const frNm = (v) => String(v).replace(".", ",");
const texteCoupleSermes = (k) => { const v = COUPLES_SERMES_COMPENSATION[k]; return Array.isArray(v) ? `${k} : puissance ${frNm(v[0])} N·m, commande ${frNm(v[1])} N·m` : `${k} : ${frNm(v)} N·m`; };
function aideCoupleSermes(element) {
  if (element && COUPLES_SERMES_COMPENSATION[element] !== undefined) return `Couple préconisé SERMES — ${texteCoupleSermes(element)}.`;
  return "Couples préconisés SERMES Electric Systems (équipements de compensation) — " + Object.keys(COUPLES_SERMES_COMPENSATION).map(texteCoupleSermes).join(" · ") + ". Choisir l'élément serré pour n'afficher que sa valeur ; pour une autre marque, se référer à sa notice.";
}
function coupleSerrageFields(typeConnexion) {
  return [
    F("taille", "Taille vis/écrou", null, LISTE_TAILLE_VIS),
    F("couple", "Couple de serrage appliqué", "N.m"),
    { key: "aide", label: "Aide technicien", longText: true, compute: (f) => aideCoupleSerrage(f.taille, typeConnexion) },
  ];
}
function coupleEtancheiteFields(sousType) {
  const tailles = Object.keys(COUPLE_ETANCHEITE_HUILE[sousType] || {});
  return [
    ...(tailles.length > 1 ? [F("taille", "Taille", null, tailles)] : []),
    F("couple", "Couple de serrage appliqué", "N.m"),
    { key: "aide", label: "Aide technicien", longText: true, compute: (f) => aideCoupleEtancheite(f.taille || tailles[0], sousType) },
  ];
}
function versMegaohms(valeur, unite) {
  const v = numOf(valeur);
  if (v === null) return null;
  if (unite === "GΩ") return v * 1000;
  if (unite === "Ω") return v / 1_000_000;
  return v; // MΩ par défaut
}
// Valeurs typiques d'isolement à froid pour transformateur sec enrobé, section "Contrôles avant
// mise en service" — repère général (confirmé identique d'un constructeur à l'autre), pas une
// norme : des valeurs nettement inférieures peuvent simplement indiquer un appareil humide, pas un
// défaut.
const ISOLEMENT_TYPIQUE_TRIHAL = { hta_terre: 250, bt_terre: 50, hta_bt: 250 };
const ISOLEMENT_TYPIQUE_LABEL = { hta_terre: "MT/masse", bt_terre: "BT/masse", hta_bt: "MT/BT" };
function isolementFields(itemType, classeIsolation, avecRealise) {
  const valeurTypique = ISOLEMENT_TYPIQUE_TRIHAL[itemType];
  const labelTypique = ISOLEMENT_TYPIQUE_LABEL[itemType];
  // Seuil PI par classe d'isolation — IEEE 43-2013, Table 3 : classe A = 1,5, classes B/F/H = 2,0.
  // Utilise la classe réellement renseignée sur l'équipement (champ "Classe d'isolation (sec)",
  // options F/H) quand elle est connue — sinon repli sur 2,0 (valeur des classes B/F/H, les plus
  // courantes) avec la mention générique dans le texte.
  const piMin = classeIsolation === "A" ? 1.5 : 2.0;
  const classeAffichee = classeIsolation ? `classe ${classeIsolation}` : "classes B/F/H";
  return [
    ...(avecRealise ? [F("realise", "Mesure réalisée ?", null, ["OUI", "NON"])] : []),
    F("typeMesure", "Type de mesure", null, LISTE_TYPE_MESURE_ISOLEMENT), F("v", "Tension d'injection", null, TENSION_ISOLEMENT),
    // Repère toujours visible, dès avant la saisie — valeurs approximatives par mesure (MT/masse =
    // 250 MΩ, BT/masse = 50 MΩ, MT/BT = 250 MΩ pour un transformateur sec enrobé).
    ...(valeurTypique ? [{
      key: "valeurTypiqueNote", label: "Valeur typique attendue pour cette mesure", longText: true,
      compute: () => `${labelTypique} ≈ ${valeurTypique} MΩ — un écart net à la baisse peut simplement indiquer un appareil humide plutôt qu'un défaut.`,
    }] : []),
    F("valeur", "Valeur"), F("unite", "Unité", null, UNITE_ISOLEMENT),
    F("temperature", "Température de l'enroulement", "°C"),
    // IR corrigé à 40 °C — contrairement au PI/DAR (des ratios entre deux mesures prises à la même
    // température, donc insensibles à celle-ci), la résistance d'isolement BRUTE dépend fortement
    // de la température : elle double environ tous les 10 °C de baisse (ou est divisée par 2 tous
    // les 10 °C de hausse). Règle générale IEEE 43-2013 (référence 40 °C) : R40 = R_mesuré ×
    // 2^((40−T)/10). Repère indicatif — certaines classes d'isolation ont des coefficients plus
    // précis (ex. 1,4 pour classe B, 1,6 pour classe F par 10 °C, selon certaines sources), non
    // repris ici faute de confirmation suffisamment fiable. Ne calcule que si température ET valeur
    // sont renseignées — jamais de température supposée par défaut.
    {
      key: "irCorrige40", label: "IR corrigé à 40 °C (repère — IEEE 43-2013, règle générale ×2 / 10 °C)", longText: true,
      compute: (f) => {
        const mesureMO = versMegaohms(f.valeur, f.unite);
        const temp = numOf(f.temperature);
        if (mesureMO === null || temp === null) return "";
        const corrige = Math.round(mesureMO * Math.pow(2, (40 - temp) / 10) * 1000) / 1000;
        return `${corrige} MΩ à 40 °C (mesuré ${mesureMO} MΩ à ${temp} °C) — règle générale (facteur ×2 par tranche de 10 °C d'écart), repère indicatif à comparer à l'historique de l'équipement, pas une formule réglementaire unique pour les transformateurs.`;
      },
    },
    // Seuil indicatif — règle largement citée (guide IEEE sur les machines tournantes, pratique
    // NETA) : résistance d'isolement minimale ≈ 1 MΩ par kV de tension d'essai. Ce n'est pas une
    // clause IEC unique et universelle pour les transformateurs (NETA propose des tables plus
    // précises selon huile/sec et plage de tension) — repère indicatif, pas une obligation légale.
    {
      key: "seuilIndicatif", label: "Seuil indicatif (repère non réglementaire — règle 1 MΩ/kV)", longText: true,
      compute: (f) => {
        const vInjection = numOf(f.v);
        const mesureMO = versMegaohms(f.valeur, f.unite);
        if (vInjection === null || mesureMO === null) return "";
        const seuilMO = vInjection / 1000; // 1 MΩ par kV de tension d'essai
        const comparaisonTrihal = valeurTypique ? ` À titre de comparaison, valeur typique ${labelTypique} ≈ ${valeurTypique} MΩ — un écart net à la baisse peut simplement indiquer un appareil humide plutôt qu'un défaut.` : "";
        if (mesureMO < seuilMO) return `⚠ ${mesureMO} MΩ mesurés, en dessous du repère indicatif de ${Math.round(seuilMO * 100) / 100} MΩ (règle 1 MΩ/kV pour ${vInjection} V d'essai) — isolement à surveiller. Repère indicatif, pas de seuil réglementaire unique pour les transformateurs.${comparaisonTrihal}`;
        return `✓ ${mesureMO} MΩ mesurés, au-dessus du repère indicatif de ${Math.round(seuilMO * 100) / 100} MΩ (règle 1 MΩ/kV pour ${vInjection} V d'essai). Repère indicatif, pas de seuil réglementaire unique pour les transformateurs.${comparaisonTrihal}`;
      },
    },
    F("pi", "PI (10/1min)"),
    // PI (indice de polarisation) — IEEE 43-2013, Table 3 : minimum recommandé 2,0 pour les
    // classes d'isolation B/F/H (la grande majorité des équipements actuels), 1,5 pour la classe A
    // (isolants anciens). Faute de champ "classe d'isolation" dans l'app, seuil 2,0 utilisé par
    // défaut (précisé dans le texte) — à ajuster si l'équipement est connu comme classe A.
    // PI ≈ 1 = aucune absorption diélectrique significative (contamination, humidité, isolant
    // dégradé). PI > 8 = isolant ancien (vernis/bakélite) potentiellement desséché et cassant, pas
    // nécessairement bon signe.
    {
      key: "aidePI", label: "Appréciation du PI (IEEE 43-2013, Table 3)", longText: true,
      compute: (f) => {
        const pi = numOf(f.pi);
        if (pi === null) return "";
        if (pi <= 1.05) return `🔴 PI = ${pi} — proche de 1, absorption diélectrique quasi nulle. Syndrome possible : contamination, humidité ou isolant dégradé. IEEE 43-2013 : minimum recommandé ${piMin} (${classeAffichee}).`;
        if (pi < piMin) return `⚠ PI = ${pi} — en dessous du minimum recommandé (${piMin}, ${classeAffichee}) mais absorption non nulle. IEEE 43-2013, Table 3. À surveiller, à confirmer avec l'historique de l'équipement.`;
        if (pi > 8) return `⚠ PI = ${pi} — supérieur à 8. Syndrome possible : isolant ancien (vernis/bakélite) desséché et cassant, pas nécessairement un signe favorable. IEEE 43-2013.`;
        return `✓ PI = ${pi} — au-dessus du minimum recommandé (${piMin}, ${classeAffichee}). IEEE 43-2013, Table 3.`;
      },
    },
    F("dar", "DAR (60/10sec)"),
    // DAR (rapport d'absorption diélectrique) — pratique courante associée à IEEE 43 : > 1,6 =
    // isolement excellent, < 1,25 = insuffisant. Zone intermédiaire = à surveiller.
    {
      key: "aideDAR", label: "Appréciation du DAR (pratique IEEE 43)", longText: true,
      compute: (f) => {
        const dar = numOf(f.dar);
        if (dar === null) return "";
        if (dar < 1) return `🔴 DAR = ${dar} — inférieur à 1, absorption diélectrique quasi nulle. Syndrome possible : contamination, humidité ou isolant dégradé.`;
        if (dar < 1.25) return `⚠ DAR = ${dar} — en dessous de 1,25, isolement insuffisant selon la pratique courante (IEEE 43). À surveiller.`;
        if (dar < 1.6) return `⚠ DAR = ${dar} — entre 1,25 et 1,6, zone intermédiaire. À surveiller.`;
        return `✓ DAR = ${dar} — supérieur ou égal à 1,6, isolement excellent selon la pratique courante (IEEE 43).`;
      },
    },
  ];
}
// Mesure d'isolement des cellules HTA (Interrupteur, Disjoncteur, Contacteur, Comptage) — même
// structure complète que celle du transformateur (type de mesure, seuil indicatif, PI, DAR...),
// avec en plus la case "Mesure réalisée ?" puisque cette section reste optionnelle pour ces
// équipements. Pas de "valeur typique" Trihal ici (repère propre aux transformateurs).
const MESURE_ISOLEMENT_CELLULE = [
  C("hta_terre", "HTA - Terre", isolementFields("hta_terre_cellule", null, true)),
  C("entre_phases", "Entre phases", isolementFields("entre_phases_cellule", null, true)),
];
function buildTransformateurSchema({ sec = false, classeIsolation = null, deuxSecondaires = false } = {}) {
  return {
    identification: [
      { key: "repere", label: "Repère / Nom de l'équipement" },
      { key: "typeIsolation", label: "Type d'isolation", options: LISTE_TYPE_ISOLATION_TDY },
      { key: "typeTransformateur", label: "Type de transformateur", options: LISTE_TYPE_TRANSFORMATEUR }, { key: "numeroSerie", label: "Numéro de série" },
      { key: "marque", label: "Marque", options: LISTE_MARQUE_TDY }, { key: "anneeMiseEnService", label: "Année de mise en service" },
      { key: "puissance", label: "Puissance (KVA)", numeric: true }, { key: "tensionPrimaire", label: "Tension primaire (KV)", numeric: true },
      { key: "couplage", label: "Couplage", options: LISTE_COUPLAGE_TDY }, { key: "tensionSecondaire", label: "Tension secondaire (V)", numeric: true },
      { key: "deuxEnroulementsSecondaires", label: "Deux enroulements secondaires", options: ["Non", "Oui"] },
      ...(deuxSecondaires ? [{ key: "tensionSecondaire2", label: "Tension secondaire 2 (V)", numeric: true }] : []),
      { key: "ucc", label: "Ucc (%)", numeric: true },
      ...(!sec ? [{ key: "typeRefroidissement", label: "Type de refroidissement", options: LISTE_REFROIDISSEMENT_TRANSFO }] : []),
      ...(sec ? [{ key: "classeIsolation", label: "Classe d'isolation (sec)", options: ["F", "H"] }] : []),
    ],
    sections: [
      { key: "environnement", title: "Contrôles environnements", items: [
        C("integrite_enveloppe", "Intégrité de l'enveloppe de protection"),
        C("proprete_transfo", "Propreté du transformateur"),
        C("indice_protection", "Indice de protection", [
          F("ip", "IP", null, LISTE_INDICE_PROTECTION),
          { key: "description", label: "Signification du code sélectionné", longText: true, compute: (f) => descriptionIP(f.ip) || "" },
        ]),
        C("mises_terre", "Mises à la terre de l'enveloppe de protection", [F("resistance", "Résistance terre-enveloppe")]),
        C("barrettes_commutation", "Barrettes de commutation", [
          F("type_reperage", "Repérage", null, ["Plot", "Position directe (commutateur à vide sans plot)"]),
          F("plot_reglage", "Plot de réglage entre (si applicable)"),
          F("valeur_tension", "Valeur de tension / position du commutateur", "V"),
        ]),
        C("raccordement_cables", "Raccordement des câbles HT et BT"),
        C("distances_refroidissement", "Distances extérieures nécessaires au refroidissement"),
        C("raccordement_sondes", "Raccordement des sondes de température aux relais thermiques"),
        ...(sec
          ? [C("etat_enrobage", "État de l'enrobage / résine"), C("ventilation_forcee", "Contrôle de la ventilation forcée")]
          : [C("niveau_huile_silicagel", "Contrôle du niveau d'huile et de l'état du silicagel (respirateur)")]),
      ]},
      { key: "mecaniques", title: "Contrôles mécaniques", items: [
        C("connexions_bt", "Contrôle des connexions BT", coupleSerrageFields("bt")),
        ...(sec ? [C("connexions_ht", "Contrôle des connexions HT", coupleSerrageFields("mt"))] : []),
        ...(sec ? [] : [
          C("couple_vis_passe_barres", "Couple de serrage — Vis de passe-barres", coupleEtancheiteFields("passe_barres")),
          C("couple_couvercle_cuve", "Couple de serrage — Vis de liaison couvercle-cuve", coupleEtancheiteFields("couvercle_cuve")),
          C("couple_bouchon_remplissage", "Couple de serrage — Bouchon de remplissage", coupleEtancheiteFields("bouchon_remplissage")),
          C("couple_bouchon_vidange", "Couple de serrage — Bouchon de vidange", coupleEtancheiteFields("bouchon_vidange")),
        ]),
      ]},
      { key: "electriques", title: "Contrôles électriques", items: [
        C("tetes_cables_hta", "Contrôle des têtes de câbles HTA"),
        C("verrouillage_cle", "Vérification du système de verrouillage à clé"),
      ]},
      { key: "relais_protection", title: "Contrôle du relais de protection", items: [
        C("type_relais", "Type", [F("valeur", "Sélection", null, sec
          ? ["Sonde PT100", "PTC", "Ziehl TR250", "Ziehl TR440", "Ziehl TR600", "Ziehl-Abegg TS1000", "Schneider MB103", "AUTRE"]
          : ["DGPT2", "DMCR", "BUCHHOLZ", "AUTRE", "MSF 220 VU (ZIEHL)", "MSF 220 K (ZIEHL)", "MSF 220 SE (ZIEHL)", "MSF 220 V (ZIEHL)", "C512 - C513 (ABB)"])]),
        ...(sec ? [] : [
          C("test_degagements_gazeux", "Test dégagements gazeux", [], ACTIONS_RELAIS_TRANSFORMATEUR),
          C("test_pression_excessive", "Test pression excessive", [F("valeur", "Valeur", "Bars")], ACTIONS_RELAIS_TRANSFORMATEUR),
        ]),
        C("test_defaut_temp_t1", "Test défaut temp T1", [F("valeur", "Valeur", "°C")], ACTIONS_RELAIS_TRANSFORMATEUR),
        C("test_defaut_temp_t2", "Test défaut temp T2", [F("valeur", "Valeur", "°C")], ACTIONS_RELAIS_TRANSFORMATEUR),
      ]},
      { key: "rapport_transformation", title: "Rapport de transformation et résistances d'enroulement", items: [
        C("rapport_par_phase", "Rapport de transformation" + (deuxSecondaires ? " — Secondaire 1" : ""), [F("l1", "L1"), F("l2", "L2"), F("l3", "L3")]),
        // CEI 60076-1 / IEEE C57.12.90 : mesure hors tension, transformateur à l'équilibre thermique
        // (pas juste après mise hors service). Chaque phase se mesure individuellement (pas de shunt
        // entre phases, contrairement à l'isolement) — un écart > 2 % entre phases indique une
        // anomalie (connexion desserrée, spire en court-circuit). La température relevée permet de
        // corriger et comparer les valeurs d'une visite à l'autre (résistance du cuivre ≈ +0,4 %/°C).
        C("resistance_enroulements_primaire", "Résistance des enroulements — Primaire", [...L1L2L3AvecToleranceEcart("mΩ"), F("temperature", "Température enroulement", "°C")]),
        C("resistance_enroulements_secondaire", "Résistance des enroulements — Secondaire" + (deuxSecondaires ? " 1" : ""), [...L1L2L3AvecToleranceEcart("mΩ"), F("temperature", "Température enroulement", "°C")]),
        ...(deuxSecondaires ? [
          C("rapport_par_phase_secondaire2", "Rapport de transformation — Secondaire 2", [F("l1", "L1"), F("l2", "L2"), F("l3", "L3")]),
          C("resistance_enroulements_secondaire2", "Résistance des enroulements — Secondaire 2", [...L1L2L3AvecToleranceEcart("mΩ"), F("temperature", "Température enroulement", "°C")]),
        ] : []),
      ]},
      { key: "mesure_isolement", title: "Mesure d'isolement", items: [
        C("hta_terre", "HTA - Terre (BT shuntée à la terre)", isolementFields("hta_terre", classeIsolation)),
        C("bt_terre", "BT" + (deuxSecondaires ? "1" : "") + " - Terre (HTA shuntée à la terre)", isolementFields("bt_terre", classeIsolation)),
        C("hta_bt", "HTA - BT" + (deuxSecondaires ? "1" : "") + " (enroulements court-circuités entre eux)", isolementFields("hta_bt", classeIsolation)),
        ...(deuxSecondaires ? [
          C("bt2_terre", "BT2 - Terre (HTA et BT1 shuntées à la terre)", isolementFields("bt_terre", classeIsolation)),
          C("hta_bt2", "HTA - BT2 (enroulements court-circuités entre eux)", isolementFields("hta_bt", classeIsolation)),
          C("bt_bt2", "BT1 - BT2 (entre les deux enroulements secondaires)", isolementFields("hta_bt", classeIsolation)),
        ] : []),
      ]},
    ],
  };
}

