// Schéma dynamique de l'Onduleur : le régime (triphasé/monophasé) de chaque réseau est choisi
// par l'utilisateur et stocké dans eq.controles.regimes_reseaux — le schéma (et donc les champs
// affichés) se recalcule en fonction de ce choix, section par section.
function getOnduleurRegimes(eq) {
  const r = (eq.controles && eq.controles.regimes_reseaux) || {};
  return {
    normalMono: r.normal === "Monophasé",
    secoursMono: r.secours === "Monophasé",
    utilisationMono: r.utilisation === "Monophasé",
    onduleurMono: r.onduleur === "Monophasé",
  };
}
function getSchema(eq) {
  if (eq.type === "Onduleur") {
    const schema = buildOnduleurSchema(getOnduleurRegimes(eq));
    let out = schema;
    // Configuration "Parallèle modulaire" : nombre de modules installés, puissance unitaire par
    // module, et répartition entre modules nécessaires à la charge, redondants (N+x, déjà
    // installés et sous tension) et en réserve (spares non installés, gardés au magasin).
    if (eq.identification?.configuration === "Parallèle modulaire") {
      const idxConfig = out.identification.findIndex((f) => f.key === "configuration");
      const champsModulaires = [
        { key: "nombreModules", label: "Nombre de modules installés", numeric: true },
        { key: "puissanceParModule", label: "Puissance par module (kVA)", numeric: true },
        { key: "nombreModulesRedondants", label: "Dont modules redondants (N+x, installés)", numeric: true },
        { key: "nombreModulesReserve", label: "Modules en réserve (spares non installés)", numeric: true },
        { key: "moduleBypass", label: "Module bypass", options: ["Séparé (module dédié)", "Intégré à chaque module de puissance"] },
      ];
      const identification = [...out.identification.slice(0, idxConfig + 1), ...champsModulaires, ...out.identification.slice(idxConfig + 1)];
      out = { ...out, identification };
    }
    // Un onduleur sécurité n'a ni réseau secours, ni by-pass / commutation R2 (RS) — masqués.
    if (eq.identification?.typeUPS === "Onduleur sécurité") {
      const ITEMS_R2_A_MASQUER = ["auto_alim_commutateur", "commutation_r0_r2", "controle_rs"];
      const sections = out.sections
        .filter((s) => s.key !== "mesures_reseau_secours" && s.key !== "bypass_synoptique")
        .map((s) => (s.key === "etat_onduleur" ? { ...s, items: s.items.filter((it) => !ITEMS_R2_A_MASQUER.includes(it.key)) } : s));
      out = { ...out, sections };
    }
    return out;
  }
  if (eq.type === "Redresseur chargeur") {
    const out = buildRedresseurSchema({ reseauMono: getOnduleurRegimes(eq).normalMono, reseau2Mono: getOnduleurRegimes(eq).secoursMono, doubleAlim: redresseurDoubleAlim(eq) });
    // Configuration modulaire (même principe que l'onduleur « Parallèle modulaire ») : modules de
    // puissance installés, puissance / courant par module, redondance N+x et modules en réserve.
    if (/^Modulaire/.test(eq.identification?.configuration || "")) {
      const idx = out.identification.findIndex((f) => f.key === "configuration");
      const champsModulaires = [
        { key: "nombreModules", label: "Nombre de modules installés", numeric: true },
        { key: "puissanceParModule", label: "Puissance par module (kW)", numeric: true },
        { key: "courantParModule", label: "Courant nominal par module (A)", numeric: true },
        { key: "nombreModulesRedondants", label: "Dont modules redondants (N+x, installés)", numeric: true },
        { key: "nombreModulesReserve", label: "Modules en réserve (spares non installés)", numeric: true },
      ];
      return { ...out, identification: [...out.identification.slice(0, idx + 1), ...champsModulaires, ...out.identification.slice(idx + 1)] };
    }
    return out;
  }
  if (eq.type === "Inverseur de source") {
    const r = (eq.controles && eq.controles.regimes_reseaux) || {};
    return buildInverseurSchema({ source1Mono: r.source1 === "Monophasé", source2Mono: r.source2 === "Monophasé", utilisationMono: r.utilisation === "Monophasé" });
  }
  if (eq.type === "Transformateur") return buildTransformateurSchema({ sec: eq.identification?.typeIsolation === "Sec (résine/enrobé)", classeIsolation: eq.identification?.classeIsolation, deuxSecondaires: eq.identification?.deuxEnroulementsSecondaires === "Oui" });
  if (eq.type === "Interrupteur HTA") return buildInterrupteurHTASchema({ avecRelais: eq.identification?.presenceRelais === "Oui" });
  if (eq.type === "Interrupteur Fusible HTA") return buildInterrupteurFusibleHTASchema({ avecRelais: eq.identification?.presenceRelais === "Oui" });
  // Bilan de puissance : écrans de mesure adaptés au régime (triphasé / monophasé) du point de mesure.
  if (eq.type === "Bilan de puissance" && eq.controles?.regimes_reseaux?.utilisation === "Monophasé") {
    const base = SCHEMAS[eq.type];
    const mono = {
      tension_simple_utilisation: C("tension_simple_utilisation", "Tension", champsMono("V", "Tension")),
      thdv_utilisation: C("thdv_utilisation", "Taux de distorsion tension", champsSeuilThdv(champsMono("%", "THdV"))),
      courant_utilisation: C("courant_utilisation", "Courant", champsMono("A", "Courant")),
      thdi_utilisation: C("thdi_utilisation", "Taux de distorsion courant", champsSeuilThdi(champsMono("%", "ThdI"))),
    };
    const sections = base.sections.map((sec) => sec.key !== "mesures_utilisation" ? sec : {
      ...sec,
      items: sec.items
        .filter((it) => it.key !== "tension_utilisation" && it.key !== "courant_neutre_utilisation")
        .map((it) => mono[it.key] || (it.key === "puissance_fp_utilisation"
          ? { ...it, fields: it.fields.filter((f) => /1$/.test(f.key)).map((f) => ({ ...f, label: f.label.replace(/ L1\b/, "") })) }
          : it)),
    });
    return { ...base, sections };
  }
  // Batterie de compensation monophasée : mesures réseau amont / aval sur une seule phase.
  if (eq.type === "Batterie de compensation" && eq.identification?.triphase === "Monophasé") {
    const base = SCHEMAS[eq.type];
    const garder = { tensions: ["u12", "thdv1"], courants: ["i1", "thdi1"] };
    const libelles = { u12: "U", thdv1: "THdV", i1: "I", thdi1: "ThdI" };
    const sections = base.sections.map((sec) => (sec.key !== "mesures_amont" && sec.key !== "mesures_aval") ? sec : {
      ...sec,
      items: sec.items.map((it) => {
        const g = /^tensions_/.test(it.key) ? garder.tensions : /^courants_/.test(it.key) ? garder.courants : null;
        if (!g) return it;
        return { ...it, fields: it.fields.filter((f) => g.includes(f.key) || f.key === "tol_max").map((f) => libelles[f.key] ? { ...f, label: libelles[f.key] } : (f.phaseKeys ? { ...f, phaseKeys: f.phaseKeys.filter((k) => g.includes(k)) } : f)) };
      }),
    });
    return { ...base, sections };
  }
  return SCHEMAS[eq.type];
}
// Classement d'un contrôle selon les niveaux de maintenance AFNOR (NF X60-000), par règle générique
// selon la nature du geste plutôt qu'un étiquetage manuel item par item :
// - "1-2" (exploitant, sans instrument) : contrôle purement visuel (état/action), sans aucune
//   valeur mesurée ni interprétation calculée à partir d'une mesure.
// - "3-4" (technicien spécialisé HT Maintenance) : dès qu'un champ porte une unité (valeur
//   mesurée) ou une interprétation calculée (longText, ex. analyse d'huile, DAR/PI) — nécessite un
//   instrument de mesure, un démontage ou une analyse.
function niveauItem(item) {
  const champs = item.fields || [];
  const aUneMesure = champs.some((f) => !!f.unit || (f.compute && f.longText));
  return aUneMesure ? "3-4" : "1-2";
}
const NIVEAUX_MAINTENANCE = ["1-2", "3-4", "1-4"];
const LABEL_NIVEAU_MAINTENANCE = { "1-2": "Niveau 1-2 — Exploitant (visuel)", "3-4": "Niveau 3-4 — Technicien spécialisé (mesures)", "1-4": "Niveau 1-4 — Gamme complète" };
// Filtre les sections/items d'un schéma selon le niveau de maintenance choisi pour l'équipement —
// "1-4" ne filtre rien (comportement historique inchangé). Les sections qui n'ont plus aucun item
// après filtrage sont retirées, pour ne pas afficher un titre de section vide.
function schemaFiltreeParNiveau(schema, niveauMaintenance) {
  if (!schema || !niveauMaintenance || niveauMaintenance === "1-4") return schema;
  const sections = schema.sections
    .map((sec) => ({ ...sec, items: sec.items.filter((it) => niveauItem(it) === niveauMaintenance) }))
    .filter((sec) => sec.items.length > 0);
  return { ...schema, sections };
}

