            return img ? <img src={img} alt={s.label} style={{ maxWidth: "100%", height: "auto" }} onLoad={(e) => { e.currentTarget.style.width = `${e.currentTarget.naturalWidth / SCHEMA_ECHELLE}px`; }} /> : null;
