    ctx.beginPath(); ctx.moveTo(xPic, cy); ctx.lineTo(x + w * 0.85, y + h * 0.92); ctx.stroke();
    drawSymboleAC(ctx, x + w * 0.35, y + h * 0.15, w * 0.16);
    drawSymboleAC(ctx, x + w * 0.35, y + h * 0.85, w * 0.16);
    drawSymboleAC(ctx, x + w * 0.68, cy, w * 0.16);
